parameters.jsonBody:
={{ (function() {
  // Parse requirements_prompt from Prompt Builder's LLM response
  let requirements_prompt = '';
  try {
    const pbRaw = $('Prompt Builder').item.json.text || '';
    const pbClean = pbRaw.trim().replace(/^`\json\s*/i,'').replace(/\s*`\\s*$/i,'').trim();
    const fi = pbClean.indexOf('{'); const li = pbClean.lastIndexOf('}');
    if (fi !== -1 && li > fi) {
      const pb = JSON.parse(pbClean.slice(fi, li + 1));
      requirements_prompt = pb.prompt || '';
    }
  } catch(e) {
    const m = ($('Prompt Builder').item.json.text||'').match(/\"prompt\"\s*:\s*\"([\s\S]+?)\"\s*[,}]/);
    if (m) requirements_prompt = m[1].replace(/\\n/g,'\n').replace(/\\t/g,'\t').replace(/\\\\\"/g,'"');
  }

  // Determine program_name: for EDIT mode use existing project name, for CREATE use LLM-generated
  const agentResult = $('AI Agent').item.json;
  const isEdit = agentResult.is_edit || agentResult.type === 'EDIT_PROJECT';
  const existingProject = $('Load Conversation Project').item.json.project;
  const programName = isEdit && existingProject?.program_name
    ? existingProject.program_name
    : $json.program_name;

  return {
    program_name:         programName,
    project_type:         isEdit && existingProject?.project_type ? existingProject.project_type : ($json.project_type || 'single_file'),
    entry_file:           isEdit && existingProject?.entry_file ? existingProject.entry_file : ($json.entry_file || ''),
    language:             $json.language || 'python',
    packages:             Array.isArray($json.packages) ? $json.packages : [],
    files:                Array.isArray($json.files)    ? $json.files    : [],
    original_request:     $node['Webhook'].json.body.message || '',
    requirements_prompt:  requirements_prompt,
    sessionId:            $node['Webhook'].json.body.sessionId || ''
  };
})()
}}

