parameters.jsonBody:
={{ (function() {
  var program_name = '';
  try { program_name = $('Code in JavaScript').item.json.program_name || ''; } catch(e) {}
  if (!program_name) {
    try { program_name = $('Execute Code').item.json.program_name || ''; } catch(e) {}
  }
  if (!program_name) {
    try { program_name = $('Load Conversation Project').item.json.project.program_name || ''; } catch(e) {}
  }
  if (!program_name) {
    try { program_name = $node['Webhook'].json.body.existing_project.program_name || ''; } catch(e) {}
  }

  var files = [];
  var filename = 'index.html';
  try { filename = $('Execute Code').item.json.filename || $('Read Code File').item.json.filename || 'index.html'; } catch(e) {}

  try {
    var raw = ($json.text || '').trim();
    // Strip markdown fences
    raw = raw.replace(/^```(?:json|python|javascript|js|html|css)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
    var fi = raw.indexOf('{'); var li = raw.lastIndexOf('}');
    if (fi !== -1 && li >= fi) {
      var parsed = JSON.parse(raw.slice(fi, li + 1));
      if (Array.isArray(parsed.patched_files)) {
        files = parsed.patched_files;
      } else if (Array.isArray(parsed.files)) {
        files = parsed.files;
      } else if (parsed.code) {
        files = [{ filename: filename, content: parsed.code }];
      }
    }
    // Fallback: if files is empty but raw has content, treat it as a single-file patch
    if (files.length === 0 && raw.length > 0) {
      files = [{ filename: filename, content: raw }];
    }
  } catch(e) {
    var cleanRaw = ($json.text || '').trim();
    cleanRaw = cleanRaw.replace(/^```(?:json|python|javascript|js|html|css)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
    if (cleanRaw.length > 0) {
      files = [{ filename: filename, content: cleanRaw }];
    } else {
      files = [];
    }
  }
  return { program_name: program_name, files: files, sessionId: $node['Webhook'].json.body.sessionId || '' };
})()
}}

