parameters.jsCode:
let programs = [];
try {
  const combineNode = $('Combine Programs').first();
  if (combineNode && combineNode.json && Array.isArray(combineNode.json.programs)) {
    programs = combineNode.json.programs;
  }
} catch (e) {
  try {
    const items = $('Get All Programs').all();
    if (Array.isArray(items)) {
      programs = items.map(item => item.json).filter(Boolean);
    }
  } catch (err) {}
}

const list = programs
  .map((p, i) => `${i + 1}. ${p.program_name || 'unnamed'} [${p.language || 'unknown'}]`)
  .join('\n');

return [{
  json: {
    output: 'Programs:\n' + (list || '(No programs available)') + '\n\nIdentifying program...'
  }
}];

const webhookData = $("Webhook").first().json;
const authHeader = webhookData.headers?.authorization || '';

const sessId = webhookData.body?.sessionId || '';
if (sessId.endsWith('_title')) {
  return [{
    json: {
      has_active_session: false,
      session_id: null,
      waiting_for_input: false,
      debug: 'bypass for title generation'
    }
  }];
}

try {
  const sessionList = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://host.docker.internal:9000/execute/sessions',
    headers: {
      'Authorization': authHeader
    },
  });

  const list = Array.isArray(sessionList) ? sessionList : [];

  const recovered = list.find(
    (s) => s && (s.running === true || String(s.running) === 'true')
  );

  if (!recovered) {
    return [{
      json: {
        has_active_session: false,
        session_id: null,
        waiting_for_input: false,
        debug: 'no live sessions',
        debug_raw: sessionList
      }
    }];
  }

  return [{
    json: {
      has_active_session: true,
      session_id: recovered.session_id,
      waiting_for_input: recovered.waiting_for_input === true || String(recovered.waiting_for_input) === 'true',
      debug: 'live session: ' + recovered.session_id
    }
  }];

} catch (e) {
  return [{
    json: {
      has_active_session: false,
      session_id: null,
      debug: 'Request Error: ' + e.message
    }
  }];
}

const data = $json;

// If running but no output yet, wait but don't fake waiting_for_input
if (data.status === 'RUNNING' && (!data.initial_output || data.initial_output === '')) {
  data.initial_output = 'Program started, waiting for output...';
  // Don't force waiting_for_input - let it naturally detect
}

return [{ json: data }];

// ?? Parse Code Output ??????????????????????????????????????????????????????
// Parses the LLM JSON response from Code Generator.
// Handles: full JSON, markdown-fenced JSON, and partial regex fallback.
// Extracts ALL fields: program_name, project_type, entry_file, language,
//   packages, files[] (new multi-file format), and legacy code string.

const raw = $json.text || '';

// ?? Step 1: strip markdown code fences if present ??????????????????????????
let cleaned = raw.trim();
// Remove leading ```json or ``` and trailing ```
cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();

// ?? Step 2: try direct JSON.parse ??????????????????????????????????????????
let parsed = null;
try {
  parsed = JSON.parse(cleaned);
} catch (e1) {
  // Try to recover from double-escaped double quotes (e.g. \\" instead of \")
  try {
    const repaired = cleaned.replace(/\\"/g, '\"');
    parsed = JSON.parse(repaired);
  } catch (e1_rep) {
    // ?? Step 3: find the outermost { ... } block and parse it ????????????????
    const firstBrace = cleaned.indexOf('{');
    const lastBrace  = cleaned.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace > firstBrace) {
      const slice_str = cleaned.slice(firstBrace, lastBrace + 1);
      try {
        parsed = JSON.parse(slice_str);
      } catch (e2) {
        try {
          const repaired_slice = slice_str.replace(/\\"/g, '\"');
          parsed = JSON.parse(repaired_slice);
        } catch (e2_rep) {
          // ?? Step 4: regex fallback for critical scalar fields ?????????????????
          parsed = {};
          const nameMatch  = raw.match(/"program_name"\s*:\s*"([^"]+)"/);
          const typeMatch  = raw.match(/"project_type"\s*:\s*"([^"]+)"/);
          const entryMatch = raw.match(/"entry_file"\s*:\s*"([^"]+)"/);
          const langMatch  = raw.match(/"language"\s*:\s*"([^"]+)"/);
          const packMatch  = raw.match(/"packages"\s*:\s*\[(.*?)\]/s);
          const codeMatch  = raw.match(/"code"\s*:\s*"([\s\S]+?)"\s*[,}]/);

          if (nameMatch)  parsed.program_name  = nameMatch[1];
          if (typeMatch)  parsed.project_type  = typeMatch[1];
          if (entryMatch) parsed.entry_file    = entryMatch[1];
          if (langMatch)  parsed.language      = langMatch[1];
          if (packMatch) {
            parsed.packages = packMatch[1]
              .split(',')
              .map(p => p.trim().replace(/^[\"']|[\"']$/g, ''))
              .filter(p => p.length > 0);
          }
          if (codeMatch) {
            parsed.code = codeMatch[1]
              .replace(/\\n/g, '\n')
              .replace(/\\t/g, '\t')
              .replace(/\\"/g, '"')
              .replace(/\\\\/g, '\\');
          }
          // files[] cannot be reliably regex-extracted so leave empty
        }
      }
    }
  }
}

if (!parsed || typeof parsed !== 'object') {
  parsed = {};
}

// ?? Step 5: normalise files[] ?????????????????????????????????????????????
// Support both {filename, content} and {path, content} shapes from LLM
let files = [];
if (Array.isArray(parsed.files) && parsed.files.length > 0) {
  files = parsed.files.map(f => ({
    filename: f.filename || f.path || f.name || '',
    content:  typeof f.content === 'string' ? f.content : ''
  })).filter(f => f.filename);
}

// ?? Step 6: if no files[] but there is a legacy 'code' field, synthesise ??
if (files.length === 0 && (parsed.code || '').length > 0) {
  const lang     = (parsed.language || 'python').toLowerCase();
  const extMap   = { python: 'py', javascript: 'js', typescript: 'ts',
                     java: 'java', go: 'go', rust: 'rs', cpp: 'cpp', c: 'c',
                     ruby: 'rb', php: 'php', html: 'html' };
  const ext      = extMap[lang] || 'py';
  const baseName = (parsed.program_name || 'program').replace(/_\\d+$/, '').replace(/[^a-z0-9_]/gi, '_');
  const fileName = baseName + '.' + ext;
  files = [{ filename: fileName, content: parsed.code }];
}

// ?? Step 7: derive project_type and enforce static_html for web pages ?????
let project_type = (parsed.project_type || '').toLowerCase().trim();
const hasHtml = files.some(f => f.filename.endsWith('.html'));
const hasExpress = files.some(f =>
  f.content.includes("require('express')") || f.content.includes("from 'express'") || f.content.includes('from express'));
const hasFlask = files.some(f =>
  f.content.includes('from flask') || f.content.includes('Flask('));
const hasFastApi = files.some(f =>
  f.content.includes('from fastapi') || f.content.includes('FastAPI('));

if (hasHtml && !hasExpress && !hasFlask && !hasFastApi) {
  project_type = 'static_html';
  parsed.packages = [];
  files = files.filter(f => !['server.js', 'package.json'].includes(f.filename.toLowerCase()));
} else if (!project_type) {
  if (hasFlask) {
    project_type = 'flask';
  } else if (hasFastApi) {
    project_type = 'fastapi';
  } else if (hasExpress) {
    project_type = 'node';
  } else if (hasHtml) {
    project_type = 'static_html';
  } else {
    project_type = 'single_file';
  }
}

// ?? Step 8: derive entry_file if not supplied ????????????????????????????
let entry_file = (parsed.entry_file || '').trim();
if (!entry_file && files.length > 0) {
  const preferred = ['index.html', 'main.html', 'app.py', 'main.py',
                     'server.js', 'index.js', 'main.js', 'app.js'];
  const found = preferred.find(pf => files.some(f => f.filename === pf));
  entry_file = found || files[0].filename;
}

let program_name = (parsed.program_name || ('program_' + Date.now())).toString();
let language     = (parsed.language || 'python').toLowerCase();
if (project_type === 'static_html') language = 'html';
let packages     = project_type === 'static_html' ? [] : (Array.isArray(parsed.packages) ? parsed.packages : []);

// ? EDIT MODE: If this is an edit, preserve the existing program_name from conversation project
try {
  const agentJson = $('AI Agent').item.json;
  const isEdit = agentJson.is_edit || agentJson.type === 'EDIT_PROJECT';
  const existingProject = $('Load Conversation Project').item.json.project;
  if (isEdit && existingProject && existingProject.program_name) {
    program_name = existingProject.program_name;
    project_type = existingProject.project_type || project_type;
    entry_file = existingProject.entry_file || entry_file;
  }
} catch(editErr) {
  // Non-fatal
}
return [{
  json: {
    program_name,
    project_type,
    entry_file,
    language,
    packages,
    files,
    code: parsed.code || (files.length > 0 ? files[0].content : '')
  }
}];

// Unix timestamp ? also passes through project_type/entry_file from Prompt Builder
const ts = Math.floor(Date.now() / 1000);

// Parse project_type and entry_file from Prompt Builder's LLM response
let project_type = 'single_file';
let entry_file   = '';

try {
  const pbRaw = $('Prompt Builder').item.json.text || '';
  // Strip markdown fences then parse
  const pbClean = pbRaw.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
  const firstBrace = pbClean.indexOf('{');
  const lastBrace  = pbClean.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace > firstBrace) {
    const pbParsed = JSON.parse(pbClean.slice(firstBrace, lastBrace + 1));
    if (pbParsed.project_type) project_type = pbParsed.project_type;
    if (pbParsed.entry_file)   entry_file   = pbParsed.entry_file;
  }
} catch(e) {
  // Fallback: regex
  const pbRaw = ($('Prompt Builder').item.json.text || '');
  const ptm = pbRaw.match(/"project_type"\s*:\s*"([^"]+)"/);
  const efm = pbRaw.match(/"entry_file"\s*:\s*"([^"]+)"/);
  if (ptm) project_type = ptm[1];
  if (efm) entry_file   = efm[1];
}

return [{ json: { timestamp: ts, project_type, entry_file } }];

const raw = $input.first().json.output || '';
if (!raw) {
  return [{ json: { error: "Empty input" } }];
}

let parsed;

// 1. Try direct JSON.parse
try {
  parsed = JSON.parse(raw);
} catch (e) {}

// 2. Try extracting from ```json ... ``` fence first
if (!parsed) {
  const fenceMatch = raw.match(/```json\s*\n([\s\S]*?)\n```/i);
  if (fenceMatch && fenceMatch[1]) {
    try {
      parsed = JSON.parse(fenceMatch[1].trim());
    } catch (e) {}
  }
}

// 3. Try extracting from ``` ... ``` fence (no language tag)
if (!parsed) {
  const fenceMatch = raw.match(/```\s*\n([\s\S]*?)\n```/i);
  if (fenceMatch && fenceMatch[1]) {
    try {
      parsed = JSON.parse(fenceMatch[1].trim());
    } catch (e) {}
  }
}

// 4. Last resort: find last { } block
if (!parsed) {
  const end = raw.lastIndexOf('}');
  let searchPos = end;

  // Walk backwards to find the { that gives valid JSON
  while (searchPos >= 0) {
    const start = raw.lastIndexOf('{', searchPos);
    if (start === -1) break;
    try {
      parsed = JSON.parse(raw.slice(start, end + 1));
      break; // success
    } catch (e) {
      searchPos = start - 1; // try earlier {
    }
  }
}

if (!parsed) {
  return [{ json: { error: "No valid JSON found", raw: raw.slice(0, 300) } }];
}

// 5. Extract Python or JS code from message field
if (parsed.message && typeof parsed.message === 'string') {
  let codeMatch = parsed.message.match(/```python\s*\n([\s\S]*?)\n```/i);
  if (!codeMatch) {
    codeMatch = parsed.message.match(/```(?:javascript|js|nodejs)\s*\n([\s\S]*?)\n```/i);
  }
  if (codeMatch && codeMatch[1]) {
    parsed.code = codeMatch[1].trim();
    parsed.message = parsed.message
      .replace(/```(?:python|javascript|js|nodejs)[\s\S]*?```/gi, '')
      .trim();
  }
}

// 6. Set filename based on language
if (parsed.code && !parsed.filename) {
  const isPython = parsed.code.includes('def ') || parsed.code.includes('print(') ||
                   parsed.program_name?.toLowerCase().includes('python');
  parsed.filename = (parsed.program_name || 'script') + (isPython ? '.py' : '.js');
}

// 7. DETERMINISTIC CONVERSATION ROUTER & INTENT PRESERVATION
let webhookBody = {};
let convProjectNode = {};
try { webhookBody = $('Webhook').item.json.body || {}; } catch(e) {}
try { convProjectNode = $('Load Conversation Project').item.json || {}; } catch(e) {}

const hasProject = !!(webhookBody.has_project || convProjectNode.has_project);
const existingProject = webhookBody.existing_project || convProjectNode.project || null;

// Non-edit classification types that MUST NEVER be converted to EDIT_PROJECT
const nonEditTypes = new Set(['CASUAL', 'HELP', 'QUESTION', 'INFORMATION', 'NEW_PROGRAM_DENIED', 'REMEMBER', 'RUN_CODE', 'CANCEL', 'INPUT_NEEDED']);

if (hasProject && existingProject && existingProject.program_name) {
  // RESPECT THE AI CLASSIFICATION EXACTLY AS-IS for CASUAL or non-edit responses
  if (nonEditTypes.has(parsed.type)) {
    delete parsed.is_edit;
  } else if (parsed.type === 'CODE_TASK' || parsed.type === 'EDIT_PROJECT') {
    // ONLY convert to EDIT_PROJECT when BOTH conditions are true:
    // 1. Conversation already owns a project (hasProject === true)
    // 2. AI explicitly classified request as a code task / edit (CODE_TASK or EDIT_PROJECT)
    parsed.type = 'EDIT_PROJECT';
    parsed.is_edit = true;
    parsed.program_name = existingProject.program_name;
    parsed.project_type = existingProject.project_type || 'single_file';
    parsed.entry_file = existingProject.entry_file || '';
  }
} else {
  // NO project exists yet for this conversation (hasProject = FALSE).
  const userText = (webhookBody.message || webhookBody.chatInput || '').toLowerCase().trim();
  const creationVerbs = ['create', 'build', 'make', 'generate', 'design', 'code', 'develop', 'building', 'creating', 'making', 'website', 'app', 'calculator'];
  const isCreationRequest = creationVerbs.some(verb => userText.includes(verb));

  if (isCreationRequest || parsed.type === 'CODE_TASK' || parsed.type === 'EDIT_PROJECT') {
    parsed.type = 'CODE_TASK';
    parsed.is_edit = false;
  }
}

return [{ json: parsed }];

// Fix Attempt Counter - tracks retries per execution using execution ID
const staticData = $getWorkflowStaticData('global');
const execId = $execution.id;

// Init or increment
if (!staticData[execId] || typeof staticData[execId].fixAttempts !== 'number') {
  staticData[execId] = { fixAttempts: 0 };
}
staticData[execId].fixAttempts++;
const currentAttempt = staticData[execId].fixAttempts;

// Purge stale execution entries (keep max 20)
const keys = Object.keys(staticData);
if (keys.length > 20) {
  delete staticData[keys[0]];
}

const MAX_ATTEMPTS = 4;

if (currentAttempt > MAX_ATTEMPTS) {
  // Reset counter
  delete staticData[execId];
  return [{
    json: {
      output: 'STATUS: FAILED\nREASON: Maximum fix attempts (' + MAX_ATTEMPTS + ') reached - the code could not be automatically repaired.\nACTION: Please review the error details below and try regenerating the program with a more specific description.\n\nLast error:\n' + (typeof $json.text === 'string' ? $json.text.slice(0, 500) : 'unknown'),
      fixAttempt: currentAttempt,
      failed: true
    }
  }];
}

// Continue normally
return [{
  json: { ...$json, fixAttempt: currentAttempt, failed: false }
}];

